-- WhatsApp passive capture (ARCHITECTURE v0.14 §5.5, §6.12; docs/plan.md §1.55): `conversation`,
-- one WhatsApp chat on one connection (direct now, groups later) with its capture setting, and
-- `conversation_change`, the append-only log of who changed it. `document.source` gains `message`
-- (a file sent in a message). Additive only: two new tables, and a source check that accepts one
-- more value, so the previous Worker keeps working. The client's default capture is a key of
-- `tenant.settings` (jsonb) and needs no column.
-- Generated by drizzle-kit; the grants, row-level security and triggers at the end are hand-written,
-- as in 0006 (contact_change) and 0029.
CREATE TABLE "conversation" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"connection_id" uuid NOT NULL,
	"channel" text NOT NULL,
	"kind" text NOT NULL,
	"contact_id" uuid,
	"external_id" text,
	"title" text NOT NULL,
	"capture" jsonb DEFAULT '{"archive":true,"attachments":"off","maxBytes":20971520}'::jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "conversation_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "conversation_channel_check" CHECK ("conversation"."channel" in ('whatsapp', 'sms')),
	CONSTRAINT "conversation_kind_check" CHECK ("conversation"."kind" in ('direct', 'group')),
	CONSTRAINT "conversation_shape_check" CHECK (("conversation"."kind" = 'direct' and "conversation"."contact_id" is not null and "conversation"."external_id" is null) or ("conversation"."kind" = 'group' and "conversation"."external_id" is not null)),
	CONSTRAINT "conversation_title_check" CHECK (length("conversation"."title") between 1 and 200),
	CONSTRAINT "conversation_external_id_check" CHECK ("conversation"."external_id" is null or length("conversation"."external_id") between 1 and 200),
	CONSTRAINT "conversation_capture_check" CHECK (jsonb_typeof("conversation"."capture") = 'object' and coalesce(jsonb_typeof("conversation"."capture"->'archive') = 'boolean', false) and coalesce("conversation"."capture"->>'attachments' in ('off', 'documents', 'all'), false) and case when jsonb_typeof("conversation"."capture"->'maxBytes') = 'number' then ("conversation"."capture"->>'maxBytes')::numeric between 1 and 33554432 else false end)
);
--> statement-breakpoint
CREATE TABLE "conversation_change" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"conversation_id" uuid NOT NULL,
	"actor_id" uuid,
	"side" text NOT NULL,
	"change" jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "conversation_change_side_check" CHECK ("conversation_change"."side" in ('client', 'operator', 'system')),
	CONSTRAINT "conversation_change_change_check" CHECK (jsonb_typeof("conversation_change"."change") = 'object')
);
