-- A conversation's capture and title change in place; the log is insert only. Nothing is deleted.
GRANT SELECT, INSERT, UPDATE ON conversation TO cs_runtime;
--> statement-breakpoint
GRANT SELECT, INSERT ON conversation_change TO cs_runtime;
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['conversation', 'conversation_change'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))',
      t);
  END LOOP;
END
$$;
