-- Only the capture, the title and updated_at change: a conversation never moves to another client,
-- connection, channel or contact, and is never deleted, whoever tries.
CREATE TRIGGER conversation_identity BEFORE UPDATE OR DELETE ON conversation
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except('capture', 'title', 'updated_at');
--> statement-breakpoint
-- The log never changes and is never deleted (as contact_change, 0006).
CREATE TRIGGER conversation_change_append_only BEFORE UPDATE OR DELETE ON conversation_change
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();